1	import Link from "next/link";
2	import { db } from "@/lib/db";
3	import { MarketingHeader } from "@/components/marketing/MarketingHeader";
4	import { MarketingFooter } from "@/components/marketing/MarketingFooter";
5	import { AnimatedHero } from "@/components/marketing/AnimatedHero";
6	import { DeployCatalog, type CatalogGroup } from "@/components/marketing/DeployCatalog";
7	import { GameServers } from "@/components/marketing/GameServers";
8	import { ClaudeBuilder } from "@/components/marketing/ClaudeBuilder";
9	import { PricingGrid } from "@/components/marketing/PricingGrid";
10	import { Reveal } from "@/components/marketing/Reveal";
11	import { Testimonials } from "@/components/marketing/Testimonials";
12	import { TrustBadges } from "@/components/marketing/TrustBadges";
13	import { NewsletterSignup } from "@/components/marketing/NewsletterSignup";
14	import { SectionHeading, FeatureCard, CtaBand } from "@/components/marketing/sections";
15	import { IconNvme, IconApps, IconShield } from "@/components/marketing/icons";
16	
17	export const dynamic = "force-dynamic";
18	
19	const CATEGORY_LABELS: Record<string, string> = {
20	  PLAIN_OS: "Operating systems",
21	  CONTROL_PANEL: "Control panels",
22	  APPLICATION: "One-click apps",
23	};
24	
25	const FALLBACK: Record<string, string[]> = {
26	  PLAIN_OS: ["Ubuntu 24.04", "Debian 13", "AlmaLinux 9", "Rocky Linux 9", "Fedora"],
27	  CONTROL_PANEL: ["cPanel", "Plesk", "CyberPanel", "Webmin", "CloudPanel", "aaPanel", "HestiaCP"],
28	  APPLICATION: ["Docker", "WordPress", "Nextcloud", "Ghost", "Node.js", "Gitea"],
29	};
30	
31	/** Claude spark mark for the flagship feature tile. */
32	function SparkIcon() {
33	  return (
34	    <svg width="22" height="22" viewBox="0 0 24 24" fill="currentColor" aria-hidden>
35	      <path d="M12 2c.4 3.9 1.7 6.6 3.9 8.1 1.4 1 3 1.5 5.1 1.9-2.1.4-3.7.9-5.1 1.9-2.2 1.5-3.5 4.2-3.9 8.1-.4-3.9-1.7-6.6-3.9-8.1-1.4-1-3-1.5-5.1-1.9 2.1-.4 3.7-.9 5.1-1.9C10.3 8.6 11.6 5.9 12 2z" />
36	    </svg>
37	  );
38	}
39	
40	export default async function Home() {
41	  const [plans, templates] = await Promise.all([
42	    db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
43	    db.osTemplate.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
44	  ]);
45	
46	  const OS_FAMILY_LABEL: Record<string, string> = {
47	    ubuntu: "Ubuntu", debian: "Debian", almalinux: "AlmaLinux", rocky: "Rocky Linux",
48	    fedora: "Fedora", centos: "CentOS", arch: "Arch Linux", alpine: "Alpine", opensuse: "openSUSE",
49	  };
50	  const byCat = (cat: string) => {
51	    const list = templates.filter((t) => t.category === cat);
52	    if (cat === "PLAIN_OS") {
53	      // Show one entry per OS family (not every point-release).
54	      const seen = new Set<string>();
55	      const fams: string[] = [];
56	      for (const t of list) {
57	        const fam = (t.family || t.name).toLowerCase();
58	        if (seen.has(fam)) continue;
59	        seen.add(fam);
60	        fams.push(OS_FAMILY_LABEL[fam] ?? (t.family ? t.family[0].toUpperCase() + t.family.slice(1) : t.name));
61	      }
62	      return fams.length ? fams : FALLBACK[cat];
63	    }
64	    const live = list.map((t) => t.name);
65	    return live.length ? live : FALLBACK[cat];
66	  };
67	
68	  const groups: CatalogGroup[] = (["PLAIN_OS", "CONTROL_PANEL", "APPLICATION"] as const).map((cat) => ({
69	    key: cat,
70	    label: CATEGORY_LABELS[cat],
71	    items: byCat(cat),
72	  }));
73	
74	  const totalImages = groups.reduce((n, g) => n + g.items.length, 0);
75	
76	  return (
77	    <div className="min-h-screen">
78	      <MarketingHeader />
79	
80	      <main>
81	        {/* ── Hero ───────────────────────────────────────────── */}
82	        <AnimatedHero imageCount={totalImages} />
83	
84	        {/* ── Benefit tiles (4, not 8) ───────────────────────── */}
85	        <section className="mx-auto max-w-6xl px-5 py-20 sm:px-6">
86	          <SectionHeading
87	            label="Why Nxeon"
88	            title="Powerful hosting, made simple"
89	            sub="Fast hardware and one-click everything — so you can launch in minutes instead of wrestling with servers."
90	          />
91	          <div className="mt-12 grid gap-5 sm:grid-cols-2 lg:grid-cols-4">
92	            <FeatureCard icon={<IconNvme />} title="Blazing NVMe speed" delay={0}>
93	              Every plan runs on enterprise NVMe SSD in a ZFS mirror. Boot, build, and load in
94	              seconds — never throttled shared disks.
95	            </FeatureCard>
96	            <FeatureCard icon={<IconApps />} title="One-click deploy" delay={60}>
97	              Launch {totalImages}+ ready-to-run images and game servers in a single click — apps,
98	              panels, and OSes configured on first boot.
99	            </FeatureCard>
100	            <FeatureCard icon={<SparkIcon />} title="Build with Claude AI" delay={120}>
101	              Connect Claude to your server and build with plain English. Describe what you want and
102	              it gets set up for you — no code.
103	            </FeatureCard>
104	            <FeatureCard icon={<IconShield />} title="Secure & backed up" delay={180}>
105	              Always-on DDoS mitigation, managed firewall, and automatic snapshots to a separate
106	              backup pool keep your data safe.
107	            </FeatureCard>
108	          </div>
109	
110	          <Reveal className="mt-12">
111	            <TrustBadges />
112	          </Reveal>
113	        </section>
114	
115	        {/* ── Deploy anything ────────────────────────────────── */}
116	        <section className="mx-auto max-w-6xl px-5 pb-20 sm:px-6">
117	          <SectionHeading
118	            label="Deploy anything"
119	            title="Your stack, ready on first boot"
120	            sub={`Pick from ${totalImages}+ images across operating systems, control panels, and one-click apps — then customise everything with full root access.`}
121	          />
122	          <Reveal className="mt-12">
123	            <DeployCatalog groups={groups} />
124	          </Reveal>
125	        </section>
126	
127	        {/* ── Game servers (headline offering) ───────────────── */}
128	        <section className="mx-auto max-w-6xl px-5 pb-20 sm:px-6">
129	          <Reveal>
130	            <GameServers />
131	          </Reveal>
132	        </section>
133	
134	        {/* ── Build with Claude AI (flagship) ────────────────── */}
135	        <section className="mx-auto max-w-6xl px-5 pb-20 sm:px-6">
136	          <Reveal>
137	            <ClaudeBuilder />
138	          </Reveal>
139	        </section>
140	
141	        {/* ── Social proof / use-cases ───────────────────────── */}
142	        <section className="mx-auto max-w-6xl px-5 pb-20 sm:px-6">
143	          <SectionHeading
144	            label="What you can run"
145	            title="Built for whatever you ship"
146	            sub="From game communities to side-projects and self-hosted stacks — here’s the kind of thing Nxeon is made for."
147	          />
148	          <div className="mt-12">
149	            <Testimonials />
150	          </div>
151	        </section>
152	
153	        {/* ── Pricing ────────────────────────────────────────── */}
154	        <section id="pricing" className="mx-auto max-w-6xl px-5 pb-20 sm:px-6">
155	          <SectionHeading
156	            label="Pricing"
157	            title="Simple, predictable pricing"
158	            sub="Pay monthly, cancel anytime. Every plan includes full root access, DDoS protection, and NVMe storage."
159	          />
160	          <Reveal className="mt-10">
161	            <PricingGrid plans={plans} />
162	          </Reveal>
163	          <p className="mt-8 text-center text-sm text-slate-500">
164	            Need a bigger box or a custom configuration?{" "}
165	            <Link href="/contact" className="text-brand-300 hover:underline">
166	              Talk to us
167	            </Link>
168	            .
169	          </p>
170	        </section>
171	
172	        {/* ── Newsletter capture ─────────────────────────────── */}
173	        <section className="mx-auto max-w-6xl px-5 pb-20 sm:px-6">
174	          <Reveal className="card mx-auto max-w-2xl text-center">
175	            <SectionHeading
176	              label="Stay in the loop"
177	              title="Product news, occasionally"
178	              sub="New one-click images, features, and the odd launch offer — straight to your inbox. No spam, unsubscribe anytime."
179	            />
180	            <div className="mt-8">
181	              <NewsletterSignup source="landing" variant="inline" />
182	            </div>
183	          </Reveal>
184	        </section>
185	
186	        {/* ── Final CTA ──────────────────────────────────────── */}
187	        <section className="mx-auto max-w-6xl px-5 pb-20 sm:px-6">
188	          <CtaBand />
189	        </section>
190	      </main>
191	
192	      <MarketingFooter />
193	    </div>
194	  );
195	}
