1	"use client";
2	
3	import Link from "next/link";
4	import { usePathname } from "next/navigation";
5	import { useEffect, useState } from "react";
6	import { NxLogo } from "./Logo";
7	
8	const NAV = [
9	  { label: "VPS", href: "/vps" },
10	  { label: "Domains", href: "/domains" },
11	  { label: "Pricing", href: "/pricing" },
12	  { label: "Features", href: "/features" },
13	  { label: "Compare", href: "/compare" },
14	  { label: "Blog", href: "/blog" },
15	];
16	
17	export function MarketingHeader() {
18	  const pathname = usePathname();
19	  const [open, setOpen] = useState(false);
20	  const [scrolled, setScrolled] = useState(false);
21	
22	  useEffect(() => {
23	    const onScroll = () => setScrolled(window.scrollY > 8);
24	    onScroll();
25	    window.addEventListener("scroll", onScroll, { passive: true });
26	    return () => window.removeEventListener("scroll", onScroll);
27	  }, []);
28	
29	  // Close the mobile menu whenever the route changes.
30	  useEffect(() => setOpen(false), [pathname]);
31	
32	  return (
33	    <header
34	      className={`sticky top-0 z-50 border-b transition-colors duration-300 ${
35	        scrolled
36	          ? "border-white/[0.06] bg-navy-950/80 backdrop-blur-xl"
37	          : "border-transparent bg-transparent"
38	      }`}
39	    >
40	      <div className="mx-auto flex h-[72px] max-w-6xl items-center justify-between px-5 sm:px-6">
41	        <NxLogo id="hdr" size={44} />
42	
43	        <nav className="hidden items-center gap-1 md:flex">
44	          {NAV.map((item) => {
45	            const active = pathname === item.href;
46	            return (
47	              <Link
48	                key={item.href}
49	                href={item.href}
50	                className={`rounded-lg px-3 py-2 text-sm font-medium transition-colors ${
51	                  active ? "text-white" : "text-slate-400 hover:text-white"
52	                }`}
53	              >
54	                {item.label}
55	              </Link>
56	            );
57	          })}
58	        </nav>
59	
60	        <div className="hidden items-center gap-2 md:flex">
61	          <Link href="/login" className="btn-ghost">
62	            Log in
63	          </Link>
64	          <Link href="/register" className="btn-primary">
65	            Get Started
66	          </Link>
67	        </div>
68	
69	        <button
70	          className="btn-ghost rounded-lg p-2 md:hidden"
71	          aria-label="Toggle menu"
72	          aria-expanded={open}
73	          onClick={() => setOpen((v) => !v)}
74	        >
75	          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
76	            {open ? <path d="M6 6l12 12M18 6 6 18" /> : <path d="M4 7h16M4 12h16M4 17h16" />}
77	          </svg>
78	        </button>
79	      </div>
80	
81	      {/* Mobile menu */}
82	      {open && (
83	        <div className="border-t border-white/[0.06] bg-navy-950/95 backdrop-blur-xl md:hidden">
84	          <nav className="mx-auto flex max-w-6xl flex-col gap-1 px-5 py-4">
85	            {NAV.map((item) => (
86	              <Link
87	                key={item.href}
88	                href={item.href}
89	                className="rounded-lg px-3 py-2.5 text-sm font-medium text-slate-300 hover:bg-white/[0.05] hover:text-white"
90	              >
91	                {item.label}
92	              </Link>
93	            ))}
94	            <div className="mt-2 flex flex-col gap-2 border-t border-white/[0.06] pt-3">
95	              <Link href="/login" className="btn-secondary w-full">
96	                Log in
97	              </Link>
98	              <Link href="/register" className="btn-primary w-full">
99	                Get Started
100	              </Link>
101	            </div>
102	          </nav>
103	        </div>
104	      )}
105	    </header>
106	  );
107	}
