1	@import "tailwindcss";
2	
3	@theme {
4	  --color-brand-50: #f2f0ff;
5	  --color-brand-100: #e4e0ff;
6	  --color-brand-200: #c9c2ff;
7	  --color-brand-300: #a89aff;
8	  --color-brand-400: #8a70fb;
9	  --color-brand-500: #6f47f5;
10	  --color-brand-600: #5f2ee8;
11	  --color-brand-700: #5124c4;
12	  --color-brand-800: #421fa0;
13	  --color-brand-900: #371d7f;
14	
15	  --color-navy-950: #060a14;
16	  --color-navy-900: #0a101f;
17	  --color-navy-850: #0d1526;
18	  --color-navy-800: #111a30;
19	  --color-navy-700: #1a2540;
20	  --color-navy-600: #253354;
21	
22	  --color-accent-blue: #3b82f6;
23	  --color-accent-cyan: #22d3ee;
24	
25	  --animate-fade-up: fade-up 0.4s ease-out both;
26	  --animate-pulse-dot: pulse-dot 2s ease-in-out infinite;
27	
28	  @keyframes fade-up {
29	    from { opacity: 0; transform: translateY(8px); }
30	    to { opacity: 1; transform: translateY(0); }
31	  }
32	  @keyframes pulse-dot {
33	    0%, 100% { box-shadow: 0 0 0 0 rgb(52 211 153 / 0.5); }
34	    50% { box-shadow: 0 0 0 5px rgb(52 211 153 / 0); }
35	  }
36	}
37	
38	body {
39	  @apply bg-navy-950 text-slate-100 antialiased;
40	  background-image:
41	    radial-gradient(ellipse 80% 50% at 20% -10%, rgb(111 71 245 / 0.13), transparent),
42	    radial-gradient(ellipse 60% 40% at 90% 0%, rgb(59 130 246 / 0.10), transparent);
43	  background-attachment: fixed;
44	}
45	
46	::-webkit-scrollbar { width: 10px; height: 10px; }
47	::-webkit-scrollbar-track { background: transparent; }
48	::-webkit-scrollbar-thumb { background: #253354; border-radius: 8px; border: 2px solid #060a14; }
49	::-webkit-scrollbar-thumb:hover { background: #34456e; }
50	
51	@layer components {
52	  /* Surfaces */
53	  .card {
54	    @apply rounded-2xl border border-white/[0.06] bg-navy-900/70 p-6 backdrop-blur-md;
55	    box-shadow: 0 1px 0 0 rgb(255 255 255 / 0.03) inset, 0 8px 32px -12px rgb(0 0 0 / 0.5);
56	  }
57	  .card-hover {
58	    @apply transition-all duration-200 hover:border-brand-500/30 hover:bg-navy-850/80;
59	  }
60	  .glass {
61	    @apply rounded-2xl border border-white/[0.08] bg-white/[0.03] backdrop-blur-xl;
62	  }
63	  .glow-brand {
64	    box-shadow: 0 0 40px -8px rgb(111 71 245 / 0.35);
65	  }
66	
67	  /* Typography */
68	  .grad-text {
69	    @apply bg-gradient-to-r from-accent-blue via-brand-400 to-brand-500 bg-clip-text text-transparent;
70	  }
71	  .page-title {
72	    @apply text-2xl font-bold tracking-tight;
73	  }
74	  .section-label {
75	    @apply text-[11px] font-semibold uppercase tracking-[0.14em] text-slate-500;
76	  }
77	
78	  /* Buttons */
79	  .btn-primary,
80	  .btn-secondary,
81	  .btn-danger,
82	  .btn-ghost {
83	    @apply inline-flex cursor-pointer items-center justify-center gap-2 rounded-xl px-4 py-2 text-sm font-semibold transition-all duration-150 disabled:cursor-not-allowed disabled:opacity-50;
84	  }
85	  .btn-primary {
86	    @apply bg-gradient-to-r from-accent-blue to-brand-500 text-white hover:brightness-110;
87	    box-shadow: 0 4px 20px -6px rgb(111 71 245 / 0.5);
88	  }
89	  .btn-secondary {
90	    @apply border border-white/10 bg-white/[0.04] text-slate-100 hover:border-white/20 hover:bg-white/[0.08];
91	  }
92	  .btn-danger {
93	    @apply border border-red-500/30 bg-red-500/10 text-red-300 hover:bg-red-500/20;
94	  }
95	  .btn-ghost {
96	    @apply text-slate-400 hover:bg-white/[0.05] hover:text-white;
97	  }
98	
99	  /* Forms */
100	  .input {
101	    @apply w-full rounded-xl border border-white/10 bg-navy-900/80 px-3.5 py-2.5 text-sm text-slate-100 outline-none transition-colors placeholder:text-slate-500 focus:border-brand-400/60 focus:ring-2 focus:ring-brand-500/20;
102	  }
103	  .label {
104	    @apply mb-1.5 block text-xs font-medium uppercase tracking-wide text-slate-400;
105	  }
106	
107	  /* Nav */
108	  .nav-item {
109	    @apply flex items-center gap-3 rounded-xl px-3 py-2 text-sm font-medium text-slate-400 transition-colors hover:bg-white/[0.05] hover:text-white;
110	  }
111	  .nav-item-active {
112	    @apply bg-gradient-to-r from-accent-blue/90 to-brand-500/90 text-white;
113	    box-shadow: 0 4px 16px -6px rgb(111 71 245 / 0.6);
114	  }
115	
116	  /* Tables */
117	  .table-shell {
118	    @apply w-full text-sm;
119	  }
120	  .table-shell thead th {
121	    @apply px-4 py-3 text-left text-[11px] font-semibold uppercase tracking-wider text-slate-500;
122	  }
123	  .table-shell tbody tr {
124	    @apply border-t border-white/[0.05] transition-colors hover:bg-white/[0.02];
125	  }
