11	  const table: [string, string][] = [
12	    ["ubuntu", "ubuntu"], ["debian", "debian"], ["almalinux", "almalinux"],
13	    ["rocky", "rocky"], ["fedora", "fedora"], ["centos", "centos"], ["arch", "arch"],
14	    ["alpine", "alpine"], ["kali", "kali"], ["suse", "opensuse"],
15	    ["cpanel", "cpanel"], ["plesk", "plesk"], ["cyberpanel", "cyberpanel"],
16	    ["webmin", "webmin"], ["cloudpanel", "cloudpanel"], ["aapanel", "aapanel"],
17	    ["hestia", "hestiacp"],
18	    ["docker", "docker"], ["wordpress", "wordpress"], ["nextcloud", "nextcloud"],
19	    ["ghost", "ghost"], ["node", "nodejs"], ["caddy", "caddy"],
20	    ["wireguard", "wireguard"], ["openvpn", "openvpn"], ["gitea", "gitea"],
21	    ["jellyfin", "jellyfin"], ["pi-hole", "pihole"], ["pihole", "pihole"],
22	    ["grafana", "grafana"], ["portainer", "portainer"], ["vaultwarden", "vaultwarden"],
23	    ["uptime", "uptimekuma"],
24	  ];
25	  for (const [k, fam] of table) if (n.includes(k)) return fam;
