1	"use client";
2	
3	import Script from "next/script";
4	
5	/**
6	 * Provider-agnostic live-chat scaffold. Renders nothing unless configured, so it
7	 * is safe to mount unconditionally in the root layout.
8	 *
9	 * Configuration precedence (first match wins):
10	 *   1. `snippet` prop — raw provider <script> body from the `livechat_snippet`
11	 *      Setting. Because this is a client component it cannot read the DB itself;
12	 *      a server parent (the layout) reads the Setting and passes it down.
13	 *   2. NEXT_PUBLIC_CRISP_ID  — Crisp website ID.
14	 *   3. NEXT_PUBLIC_TAWK_ID   — tawk.to property/widget id, formatted
15	 *      "<propertyId>/<widgetId>" (or just "<propertyId>" → default widget).
16	 *
17	 * No hard dependency on any provider; all three paths are optional.
18	 */
19	export default function LiveChat({ snippet }: { snippet?: string } = {}) {
20	  const raw = snippet?.trim();
21	  const crispId = process.env.NEXT_PUBLIC_CRISP_ID;
22	  const tawkId = process.env.NEXT_PUBLIC_TAWK_ID;
23	
24	  // 1. Custom snippet from the livechat_snippet Setting (any provider).
25	  if (raw) {
26	    return (
27	      <Script id="livechat-custom" strategy="afterInteractive">
28	        {raw}
29	      </Script>
30	    );
31	  }
32	
33	  // 2. Crisp.
34	  if (crispId) {
35	    return (
36	      <Script id="livechat-crisp" strategy="afterInteractive">
37	        {`window.$crisp=[];window.CRISP_WEBSITE_ID="${crispId}";(function(){var d=document,s=d.createElement("script");s.src="https://client.crisp.chat/l.js";s.async=1;d.getElementsByTagName("head")[0].appendChild(s);})();`}
38	      </Script>
39	    );
40	  }
41	
42	  // 3. tawk.to.
43	  if (tawkId) {
44	    const [propertyId, widgetId = "default"] = tawkId.split("/");
45	    return (
46	      <Script id="livechat-tawk" strategy="afterInteractive">
47	        {`var Tawk_API=Tawk_API||{},Tawk_LoadStart=new Date();(function(){var s1=document.createElement("script"),s0=document.getElementsByTagName("script")[0];s1.async=true;s1.src="https://embed.tawk.to/${propertyId}/${widgetId}";s1.charset="UTF-8";s1.setAttribute("crossorigin","*");s0.parentNode.insertBefore(s1,s0);})();`}
48	      </Script>
49	    );
50	  }
51	
52	  // Not configured → render nothing.
53	  return null;
54	}
